        return;
    }

    String user_text = server.arg("text");
    Serial.println("Вопрос: " + user_text);

    server.send(200, "text/html", 
        "<html><head><meta charset='UTF-8'></head><body>"
        "<h1>Обработка...</h1>"
        "<p>Ваш вопрос: " + user_text + "</p>"
        "<p>Проверьте колонку.</p>"
        "<a href='/'>Назад</a>"
        "</body></html>");

    String ai_response = aiClient->chat(user_text);
    Serial.println("Ответ ИИ: " + ai_response);

    if (ai_response.length() == 0) {
        Serial.println("Ошибка: пустой ответ от ИИ");
        return;
    }

    if (fetch_tts(ai_response)) {
        Serial.println("Начинаем воспроизведение...");
    }
}

// ==================== SETUP ====================
void setup() {
