    Serial.println("\n=== ESP32 AI Ассистент ===");

    if (psramFound()) {
        Serial.println("PSRAM найден: " + String(ESP.getPsramSize() / 1024) + " KB");
    } else {
        Serial.println("PSRAM не найден");
    }

    WiFi.begin(ssid, password);
    Serial.print("Подключение к Wi-Fi");
    while (WiFi.status() != WL_CONNECTED) {
        delay(500);
        Serial.print(".");
    }
    Serial.println("\nWi-Fi подключен. IP: " + WiFi.localIP().toString());

    String api_key = get_api_key();
    aiClient = new ESP32_AI_Connect("deepseek", api_key.c_str());
    aiClient->set_system_prompt("Ты полезный ассистент. Отвечай кратко и по делу на русском языке.");
    Serial.println("AI-клиент инициализирован (DeepSeek)");

    server.on("/", []() {
        server.send(200, "text/html", html_page);
    });
    server.on("/ask", HTTP_POST, handle_ask);
    server.begin();
    Serial.println("Веб-сервер запущен");

    a2dp_source.set_data_callback(get_sound_data);
    a2dp_source.start(speaker_name);
    Serial.println("Bluetooth: попытка подключения к " + String(speaker_name));
}

